/// Path of the core module (the merge-conflict pair edits one line of it).
pub(crate) const CORE_INDEX_PATH: &str = "packages/core/src/index.js";

/// The greeting line the merge-conflict pair rewrites differently on each side.
pub(crate) const CONFLICT_BASE_LINE: &str = "  return \"Hello, \" + name + \"!\";";
/// Side A of the merge-conflict pair.
pub(crate) const CONFLICT_LINE_A: &str = "  return \"Hi, \" + name + \"!\";";
/// Side B of the merge-conflict pair.
pub(crate) const CONFLICT_LINE_B: &str = "  return \"Welcome, \" + name + \".\";";

const CORE_INDEX: &str = "// @fixture/core: greeting and version helpers.\nexport const VERSION = \"1.0.0\";\n\nexport function greet(name) {\n  return \"Hello, \" + name + \"!\";\n}\n\nexport function shout(text) {\n  return text.toUpperCase();\n}\n";

/// Path of the range helper that carries the seeded review defect.
pub(crate) const RANGE_PATH: &str = "packages/util/src/range.js";

/// The correct loop line (inclusive on both ends).
pub(crate) const RANGE_CORRECT_LINE: &str = "  for (let i = start; i <= end; i++) {";
/// The seeded defect: the loop stops one short.
pub(crate) const RANGE_DEFECTIVE_LINE: &str = "  for (let i = start; i < end; i++) {";

const RANGE_SOURCE: &str = "// @fixture/util: integer ranges.\n// range(start, end) includes BOTH ends.\nexport function range(start, end) {\n  const out = [];\n  for (let i = start; i <= end; i++) {\n    out.push(i);\n  }\n  return out;\n}\n";

/// Path of the schema file the schema-overlap pair both touch.
pub(crate) const SCHEMA_PATH: &str = "packages/store/schema.sql";

/// The `tickets` section anchor that schema-overlap side A extends.
pub(crate) const SCHEMA_TICKETS_LINE: &str = "  title TEXT NOT NULL";
/// The `runs` section anchor that schema-overlap side B extends.
pub(crate) const SCHEMA_RUNS_LINE: &str = "  ticket_id INTEGER NOT NULL";

const SCHEMA_SQL: &str = "-- Fixture schema.\n\n-- Section 1: tickets\nCREATE TABLE tickets (\n  id INTEGER PRIMARY KEY,\n  title TEXT NOT NULL\n);\n\n-- Section 2: indexes (unchanged by either side)\n-- (none yet)\n-- (none yet)\n-- (none yet)\n\n-- Section 3: runs\nCREATE TABLE runs (\n  id INTEGER PRIMARY KEY,\n  ticket_id INTEGER NOT NULL\n);\n";

