/// Normalises line endings to LF (a checkout with `autocrlf` must not change the bytes written to a fixture).
pub(crate) fn lf(text: &str) -> String {
    text.replace("\r\n", "\n")
}

/// `range.js` with the seeded off-by-one.
pub(crate) fn range_with_defect() -> String {
    RANGE_SOURCE.replace(RANGE_CORRECT_LINE, RANGE_DEFECTIVE_LINE)
}

/// `index.js` with the greeting line replaced.
pub(crate) fn core_with_greeting(line: &str) -> String {
    CORE_INDEX.replace(CONFLICT_BASE_LINE, line)
}

/// `schema.sql` with the `tickets` section extended by an `owner` column.
pub(crate) fn schema_side_a() -> String {
    SCHEMA_SQL.replace(
        SCHEMA_TICKETS_LINE,
        &format!("{SCHEMA_TICKETS_LINE},\n  owner TEXT"),
    )
}

/// `schema.sql` with the `runs` section extended by a `status` column.
pub(crate) fn schema_side_b() -> String {
    SCHEMA_SQL.replace(
        SCHEMA_RUNS_LINE,
        &format!("{SCHEMA_RUNS_LINE},\n  status TEXT"),
    )
}

/// The 1-based line number of `needle` (a whole line) in `text`.
pub(crate) fn line_number_of(text: &str, needle: &str) -> Option<usize> {
    text.lines().position(|l| l == needle).map(|i| i + 1)
}

/// The correct `range.js`, for line-number computations.
pub(crate) fn range_source() -> &'static str {
    RANGE_SOURCE
}
